package com.farmingcontract.farming;

import com.farmingcontract.data.ContractCrop;
import com.farmingcontract.data.PatchType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Sanity checks on the vendored varbit decode tables.
 *
 * <p>These do not re-verify RuneLite's data — that is copied verbatim under BSD-2 and is the
 * upstream project's responsibility. They confirm the vendoring did not lose or mangle anything:
 * every Farming Guild patch type still decodes, empty patches read as weeds, and the patch types
 * this plugin never queries are the inert stubs.
 */
public class PatchDecodeTest
{
	@Test
	public void everyContractPatchTypeDecodesAFreshPatch()
	{
		for (PatchType type : PatchType.values())
		{
			PatchState state = type.getImplementation().forVarbitValue(0);
			assertNotNull(type + " failed to decode varbit value 0", state);
			assertEquals(type + " should read as weeds when empty",
				Produce.WEEDS, state.getProduce());
		}
	}

	@Test
	public void decodersCoverTheWholeVarbitRangeWithoutThrowing()
	{
		for (PatchType type : PatchType.values())
		{
			for (int value = 0; value <= 255; value++)
			{
				// Must not throw; null is a legitimate "unrecognised value".
				type.getImplementation().forVarbitValue(value);
			}
		}
	}

	@Test
	public void nonGuildPatchTypesAreInertStubs()
	{
		// These exist only so the vendored Produce enum still compiles; they are never queried.
		assertNull(PatchImplementation.HOPS.forVarbitValue(0));
		assertNull(PatchImplementation.CALQUAT.forVarbitValue(4));
		assertNull(PatchImplementation.SPIRIT_TREE.forVarbitValue(1));
		assertNull(PatchImplementation.COMPOST.forVarbitValue(1));
		assertNull(PatchImplementation.MUSHROOM.forVarbitValue(5));
	}

	@Test
	public void everyContractCropIsReachableFromItsPatchDecoder()
	{
		// For each contract crop, some varbit value in its patch type must decode to that produce.
		for (ContractCrop crop : ContractCrop.values())
		{
			boolean found = false;
			for (int value = 0; value <= 255 && !found; value++)
			{
				PatchState state = crop.getPatchType().getImplementation().forVarbitValue(value);
				if (state != null && state.getProduce() == crop.getProduce())
				{
					found = true;
				}
			}
			assertTrue(crop.name() + " is not reachable from " + crop.getPatchType()
				+ "'s decode table", found);
		}
	}

	@Test
	public void growingAndHarvestableStagesAreConsistent()
	{
		// A tree patch mid-growth should report a positive tick rate and sane stage bounds.
		for (int value = 0; value <= 255; value++)
		{
			PatchState state = PatchType.TREE.getImplementation().forVarbitValue(value);
			if (state == null || state.getCropState() != CropState.GROWING)
			{
				continue;
			}
			assertTrue("stage should be within stages for value " + value,
				state.getStage() < state.getStages());
			assertTrue("growing crops should have a tick rate for value " + value,
				state.getTickRate() > 0);
		}
	}
}

package com.farmingcontract;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Dev launcher: starts a RuneLite client with this plugin side-loaded, for manual in-game testing.
 * Run with {@code ./gradlew run}.
 */
public class FarmingContractHelperPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(FarmingContractHelperPlugin.class);
		RuneLite.main(args);
	}
}

package com.farmingcontract;

import com.farmingcontract.ItemAvailability.Status;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Inventory quantity calculations, noted-item handling, and the honesty rules around unloaded
 * container data. Spec test category 6.
 */
public class ItemAvailabilityTest
{
	/**
	 * A gardener payment: notes are accepted.
	 */
	private static ItemAvailability payment(int required, int carried, int noted, int bank, int vault)
	{
		return ItemAvailability.of(required, carried, noted, bank, vault, true);
	}

	/**
	 * A seed or sapling: notes are not plantable.
	 */
	private static ItemAvailability seed(int required, int carried, int noted, int bank, int vault)
	{
		return ItemAvailability.of(required, carried, noted, bank, vault, false);
	}

	// -------------------------------------------------- carried

	@Test
	public void satisfiedWhenInventoryMeetsTheRequirement()
	{
		ItemAvailability a = payment(5, 5, 0, -1, -1);
		assertTrue(a.isSatisfiedFromInventory());
		assertEquals(Status.HAVE, a.getStatus());
		assertEquals("5 / 5", a.getInventoryProgress());
	}

	@Test
	public void shortWhenInventoryIsBelowTheRequirement()
	{
		ItemAvailability a = payment(5, 2, 0, 0, 0);
		assertFalse(a.isSatisfiedFromInventory());
		assertEquals(Status.MISSING, a.getStatus());
	}

	// -------------------------------------------------- noted items

	@Test
	public void notedPaymentCountsAsAvailable()
	{
		// 25 noted coconuts pay for a magic tree just as well as 25 loose ones.
		ItemAvailability a = payment(25, 0, 25, -1, -1);
		assertTrue(a.isSatisfiedFromInventory());
		assertEquals(Status.HAVE_NOTED, a.getStatus());
		assertTrue(a.isCoveredByNote());
	}

	@Test
	public void notedAndLoosePaymentsCombine()
	{
		ItemAvailability a = payment(25, 10, 15, -1, -1);
		assertTrue(a.isSatisfiedFromInventory());
		assertEquals(25, a.getUsableInInventory());
		assertEquals(Status.HAVE_NOTED, a.getStatus());
	}

	@Test
	public void notedSeedDoesNotCountAsPlantable()
	{
		// A noted sapling cannot be planted, so this is not satisfied.
		ItemAvailability a = seed(1, 0, 1, 0, 0);
		assertFalse(a.isSatisfiedFromInventory());
		assertEquals(0, a.getUsableInInventory());
		assertTrue(a.hasUnusableNote());
		assertEquals(Status.MISSING, a.getStatus());
	}

	@Test
	public void unnotedSeedIsPlantable()
	{
		ItemAvailability a = seed(3, 3, 0, -1, -1);
		assertTrue(a.isSatisfiedFromInventory());
		assertFalse(a.hasUnusableNote());
		assertEquals(Status.HAVE, a.getStatus());
	}

	@Test
	public void carriedItemIsNotReportedAsCoveredByANote()
	{
		ItemAvailability a = payment(5, 5, 3, -1, -1);
		assertEquals(Status.HAVE, a.getStatus());
		assertFalse(a.isCoveredByNote());
	}

	// -------------------------------------------------- bank and vault

	@Test
	public void itemsInBankAreShownAsInStorageNotMissing()
	{
		// The behaviour asked for: having it in the bank is not the same as not having it.
		ItemAvailability a = payment(25, 0, 0, 25, 0);
		assertEquals(Status.IN_STORAGE, a.getStatus());
		assertFalse(a.isDefinitelyShort());
		assertEquals("bank: 25", a.getStorageDescription());
	}

	@Test
	public void seedVaultCountsAsStorage()
	{
		ItemAvailability a = seed(3, 0, 0, 0, 3);
		assertEquals(Status.IN_STORAGE, a.getStatus());
		assertEquals("vault: 3", a.getStorageDescription());
	}

	@Test
	public void bankAndVaultAreBothDescribed()
	{
		ItemAvailability a = seed(10, 0, 0, 4, 6);
		assertEquals(Status.IN_STORAGE, a.getStatus());
		assertEquals("bank: 4, vault: 6", a.getStorageDescription());
	}

	@Test
	public void inventoryAndStorageCombineToSatisfy()
	{
		ItemAvailability a = payment(5, 1, 0, 3, 1);
		assertFalse(a.isSatisfiedFromInventory());
		assertTrue(a.isSatisfiedFromKnownSources());
		assertEquals(Status.IN_STORAGE, a.getStatus());
	}

	// -------------------------------------------------- unknown sources

	@Test
	public void unopenedBankIsUnknownNotEmpty()
	{
		ItemAvailability a = payment(5, 2, 0, -1, -1);
		assertFalse(a.isBankKnown());
		assertFalse(a.isSeedVaultKnown());
		assertFalse(a.isSourcesLoaded());
		// Short in the inventory, but we must NOT claim the player lacks the item.
		assertFalse(a.isDefinitelyShort());
		assertEquals(Status.UNKNOWN, a.getStatus());
	}

	@Test
	public void definitelyShortOnlyWhenEverySourceHasBeenSeen()
	{
		assertTrue(payment(5, 2, 0, 0, 0).isDefinitelyShort());
		assertFalse(payment(5, 2, 0, 0, -1).isDefinitelyShort());
		assertEquals(Status.UNKNOWN, payment(5, 2, 0, 0, -1).getStatus());
	}

	@Test
	public void knownTotalSumsOnlyLoadedSources()
	{
		assertEquals(2, payment(5, 2, 0, -1, -1).getKnownTotal());
		assertEquals(5, payment(5, 2, 0, 3, -1).getKnownTotal());
		assertEquals(9, payment(5, 2, 0, 3, 4).getKnownTotal());
	}

	@Test
	public void storageDescriptionIsNullWhenNothingKnown()
	{
		assertNull(payment(5, 0, 0, -1, -1).getStorageDescription());
		assertNull(payment(5, 0, 0, 0, 0).getStorageDescription());
	}

	// -------------------------------------------------- nothing required

	@Test
	public void nothingRequiredIsNotAShortfall()
	{
		ItemAvailability none = payment(0, 0, 0, -1, -1);
		assertTrue(none.isNotRequired());
		assertTrue(none.isSatisfiedFromInventory());
		assertEquals(Status.NOT_REQUIRED, none.getStatus());
	}

	@Test
	public void unknownFactoryRequiresNothing()
	{
		ItemAvailability a = ItemAvailability.unknown();
		assertTrue(a.isNotRequired());
		assertFalse(a.isBankKnown());
		assertFalse(a.isSeedVaultKnown());
		assertEquals(Status.NOT_REQUIRED, a.getStatus());
	}
}

package com.farmingcontract.data;

import com.farmingcontract.farming.Produce;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;

/**
 * Static contract data: crop to patch, crop to seed, seed quantities, protection payments and
 * basket/sack quantities. Spec test categories 1-5 and 14.
 */
public class ContractDataTest
{
	// -------------------------------------------------- 1. crop to patch mapping

	@Test
	public void cropsMapToTheCorrectPatchType()
	{
		assertEquals(PatchType.TREE, ContractCrop.MAPLE.getPatchType());
		assertEquals(PatchType.FRUIT_TREE, ContractCrop.PAPAYA.getPatchType());
		assertEquals(PatchType.HERB, ContractCrop.SNAPDRAGON.getPatchType());
		assertEquals(PatchType.ALLOTMENT, ContractCrop.WATERMELON.getPatchType());
		assertEquals(PatchType.FLOWER, ContractCrop.WHITE_LILY.getPatchType());
		assertEquals(PatchType.BUSH, ContractCrop.POISON_IVY.getPatchType());
		assertEquals(PatchType.CACTUS, ContractCrop.POTATO_CACTUS.getPatchType());
		assertEquals(PatchType.CELASTRUS, ContractCrop.CELASTRUS.getPatchType());
		assertEquals(PatchType.REDWOOD, ContractCrop.REDWOOD.getPatchType());
	}

	@Test
	public void everyPatchTypeHasAtLeastOneVarbitAndALocation()
	{
		for (PatchType type : PatchType.values())
		{
			assertFalse(type.name(), type.getVarbitList().isEmpty());
			assertFalse(type.name(), type.getLocationDescription().isEmpty());
			assertNotNull(type.name(), type.getImplementation());
		}
	}

	@Test
	public void onlyAllotmentIsDuplicatedInTheGuild()
	{
		assertEquals(2, PatchType.ALLOTMENT.getVarbitList().size());
		for (PatchType type : PatchType.values())
		{
			if (type != PatchType.ALLOTMENT)
			{
				assertEquals(type.name(), 1, type.getVarbitList().size());
			}
		}
	}

	// -------------------------------------------------- 2. crop to seed mapping

	@Test
	public void cropsMapToTheCorrectSeedOrSapling()
	{
		assertEquals(ItemID.PLANTPOT_MAPLE_SAPLING, ContractCrop.MAPLE.getSeedItemId());
		assertEquals(ItemID.PLANTPOT_OAK_SAPLING, ContractCrop.OAK.getSeedItemId());
		assertEquals(ItemID.RANARR_SEED, ContractCrop.RANARR.getSeedItemId());
		assertEquals(ItemID.WATERMELON_SEED, ContractCrop.WATERMELON.getSeedItemId());
		assertEquals(ItemID.POTATO_CACTUS_SEED, ContractCrop.POTATO_CACTUS.getSeedItemId());
		assertEquals(ItemID.PLANTPOT_REDWOOD_TREE_SAPLING, ContractCrop.REDWOOD.getSeedItemId());
	}

	@Test
	public void treeContractsRequireSaplingsNotRawSeeds()
	{
		// Jane's contract is satisfied by planting a sapling; the raw seed must be potted first.
		assertEquals(ItemID.PLANTPOT_OAK_SAPLING, ContractCrop.OAK.getSeedItemId());
		assertEquals(ItemID.PLANTPOT_APPLE_SAPLING, ContractCrop.APPLE.getSeedItemId());
		assertEquals(ItemID.PLANTPOT_CELASTRUS_TREE_SAPLING, ContractCrop.CELASTRUS.getSeedItemId());
		assertTrue(ContractCrop.OAK.getSeedName().endsWith("sapling"));
		assertTrue(ContractCrop.DRAGONFRUIT.getSeedName().endsWith("sapling"));
	}

	@Test
	public void everyCropHasADistinctNonZeroSeedName()
	{
		Set<String> names = new HashSet<>();
		for (ContractCrop crop : ContractCrop.values())
		{
			assertTrue(crop.name(), crop.getSeedItemId() > 0);
			assertFalse(crop.name(), crop.getSeedName().isEmpty());
			assertTrue("duplicate seed name " + crop.getSeedName(), names.add(crop.getSeedName()));
		}
	}

	// -------------------------------------------------- 3. seed quantities

	@Test
	public void allotmentsTakeThreeSeedsEverythingElseTakesOne()
	{
		assertEquals(3, ContractCrop.POTATO.getSeedQuantity());
		assertEquals(3, ContractCrop.WATERMELON.getSeedQuantity());
		assertEquals(3, ContractCrop.SNAPE_GRASS.getSeedQuantity());

		for (ContractCrop crop : ContractCrop.values())
		{
			int expected = crop.getPatchType() == PatchType.ALLOTMENT ? 3 : 1;
			assertEquals(crop.name(), expected, crop.getSeedQuantity());
		}
	}

	// -------------------------------------------------- 4. protection payment mappings

	@Test
	public void protectionPaymentsAreCropSpecific()
	{
		// The spec's worked example.
		ProtectionPayment maple = ContractCrop.MAPLE.getProtection();
		assertTrue(maple.isAvailable());
		assertEquals(ItemID.BASKET_ORANGE_5, maple.getItemId());
		assertEquals(1, maple.getQuantity());
		assertEquals("1 Basket of oranges", maple.getDescription());
		assertEquals(5, maple.getLooseQuantity());
		assertEquals(ItemID.ORANGE, maple.getLooseItemId());
		assertEquals("5 Oranges", maple.getContentsDescription());
	}

	@Test
	public void loosePaymentsCarryNoContainer()
	{
		ProtectionPayment yew = ContractCrop.YEW.getProtection();
		assertTrue(yew.isAvailable());
		assertFalse(yew.isContainerRequired());
		assertEquals(ItemID.CACTUS_SPINE, yew.getItemId());
		assertEquals(10, yew.getQuantity());
		assertNull(yew.getContentsDescription());

		ProtectionPayment magic = ContractCrop.MAGIC.getProtection();
		assertEquals(ItemID.COCONUT, magic.getItemId());
		assertEquals(25, magic.getQuantity());

		ProtectionPayment redwood = ContractCrop.REDWOOD.getProtection();
		assertEquals(ItemID.DRAGONFRUIT, redwood.getItemId());
		assertEquals(6, redwood.getQuantity());
	}

	@Test
	public void potatoIsPaidInCompost()
	{
		ProtectionPayment potato = ContractCrop.POTATO.getProtection();
		assertEquals(ItemID.BUCKET_COMPOST, potato.getItemId());
		assertEquals(2, potato.getQuantity());
		assertFalse(potato.isContainerRequired());
	}

	// -------------------------------------------------- 5. basket and sack quantities

	@Test
	public void basketsHoldFiveAndSacksHoldTen()
	{
		assertEquals(5, ProtectionPayment.BASKET_CAPACITY);
		assertEquals(10, ProtectionPayment.SACK_CAPACITY);
	}

	@Test
	public void multipleContainersMultiplyTheLooseQuantity()
	{
		// Curry: 5 baskets of bananas = 25 bananas.
		ProtectionPayment curry = ContractCrop.CURRY.getProtection();
		assertEquals(5, curry.getQuantity());
		assertEquals(25, curry.getLooseQuantity());
		assertEquals("25 Bananas", curry.getContentsDescription());

		// Redberries: 4 sacks of cabbages = 40 cabbages.
		ProtectionPayment redberries = ContractCrop.REDBERRIES.getProtection();
		assertEquals(4, redberries.getQuantity());
		assertEquals(40, redberries.getLooseQuantity());
		assertEquals(ItemID.SACK_CABBAGE_10, redberries.getItemId());

		// Tomato: 2 sacks of cabbages = 20 cabbages.
		assertEquals(20, ContractCrop.TOMATO.getProtection().getLooseQuantity());
	}

	@Test
	public void containerPaymentsUseTheFilledContainerId()
	{
		for (ContractCrop crop : ContractCrop.values())
		{
			ProtectionPayment payment = crop.getProtection();
			if (payment.isContainerRequired())
			{
				int perContainer = payment.getLooseQuantity() / payment.getQuantity();
				assertTrue(crop.name() + " container capacity " + perContainer,
					perContainer == ProtectionPayment.BASKET_CAPACITY
						|| perContainer == ProtectionPayment.SACK_CAPACITY);
			}
		}
	}

	// -------------------------------------------------- 14. crops without protection

	@Test
	public void herbsAndFlowersCannotBeProtected()
	{
		for (ContractCrop crop : ContractCrop.values())
		{
			if (crop.getPatchType() == PatchType.HERB || crop.getPatchType() == PatchType.FLOWER)
			{
				assertSame(crop.name(), ProtectionPayment.NONE, crop.getProtection());
				assertFalse(crop.name(), crop.getProtection().isAvailable());
				assertEquals("Not available", crop.getProtection().getDescription());
			}
		}
	}

	@Test
	public void poisonIvyNeedsNoProtection()
	{
		// Poison ivy cannot become diseased, so there is nothing to protect against.
		assertFalse(ContractCrop.POISON_IVY.getProtection().isAvailable());
	}

	@Test
	public void everyNonHerbNonFlowerCropExceptPoisonIvyHasAPayment()
	{
		for (ContractCrop crop : ContractCrop.values())
		{
			boolean expectedNone = crop.getPatchType() == PatchType.HERB
				|| crop.getPatchType() == PatchType.FLOWER
				|| crop == ContractCrop.POISON_IVY;
			assertEquals(crop.name(), !expectedNone, crop.getProtection().isAvailable());
		}
	}

	// -------------------------------------------------- lookups and tiers

	@Test
	public void contractNameLookupIsCaseInsensitive()
	{
		assertSame(ContractCrop.MAPLE, ContractCrop.forContractName("Maple tree"));
		assertSame(ContractCrop.MAPLE, ContractCrop.forContractName("maple tree"));
		assertSame(ContractCrop.MAPLE, ContractCrop.forContractName("  MAPLE TREE  "));
		assertNull(ContractCrop.forContractName("Banana bread"));
		assertNull(ContractCrop.forContractName(null));
	}

	@Test
	public void produceLookupResolvesBackToTheCrop()
	{
		assertSame(ContractCrop.MAPLE, ContractCrop.forProduce(Produce.MAPLE));
		assertSame(ContractCrop.TORSTOL, ContractCrop.forProduce(Produce.TORSTOL));
		assertNull(ContractCrop.forProduce(null));
		// Weeds are not a contract crop.
		assertNull(ContractCrop.forProduce(Produce.WEEDS));
	}

	@Test
	public void everyCropBelongsToAtLeastOneTier()
	{
		for (ContractCrop crop : ContractCrop.values())
		{
			assertFalse(crop.name(), crop.getTiers().isEmpty());
		}
	}

	@Test
	public void representativeEasyMediumAndHardContracts()
	{
		// Easy
		assertTrue(ContractCrop.POTATO.getTiers().contains(ContractTier.EASY));
		assertEquals(PatchType.ALLOTMENT, ContractCrop.POTATO.getPatchType());

		// Medium
		assertTrue(ContractCrop.PAPAYA.getTiers().contains(ContractTier.MEDIUM));
		assertEquals(ItemID.PINEAPPLE, ContractCrop.PAPAYA.getProtection().getItemId());
		assertEquals(10, ContractCrop.PAPAYA.getProtection().getQuantity());

		// Hard
		assertTrue(ContractCrop.TORSTOL.getTiers().contains(ContractTier.HARD));
		assertFalse(ContractCrop.TORSTOL.getProtection().isAvailable());
		assertTrue(ContractCrop.REDWOOD.getTiers().contains(ContractTier.HARD));

		// Maple spans all three tiers.
		assertEquals(EnumSet.allOf(ContractTier.class), ContractCrop.MAPLE.getTiers());
	}

	@Test
	public void everyCropsProduceNameMatchesItsContractName()
	{
		for (ContractCrop crop : ContractCrop.values())
		{
			assertEquals(crop.name(), crop.getProduce().getContractName(), crop.getContractName());
			assertTrue(crop.name(), crop.getProduceItemId() > 0);
		}
	}
}

package com.farmingcontract;

import com.farmingcontract.data.ContractCrop;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Contract dialogue and game-message parsing. Spec test categories 7 and 8.
 */
public class ContractParserTest
{
	// -------------------------------------------------- 7. contract dialogue parsing

	@Test
	public void parsesTheWeNeedYouToGrowWording()
	{
		assertSame(ContractCrop.MAPLE,
			ContractParser.parseAssignment("We need you to grow a Maple tree for us?"));
		assertSame(ContractCrop.GUAM,
			ContractParser.parseAssignment("We need you to grow some Guam for us?"));
	}

	@Test
	public void parsesThePleaseCouldYouGrowWording()
	{
		assertSame(ContractCrop.SNAPDRAGON,
			ContractParser.parseAssignment("Please could you grow some Snapdragon for us?"));
		assertSame(ContractCrop.APPLE,
			ContractParser.parseAssignment("Please could you grow an Apple tree for us?"));
	}

	@Test
	public void parsesTheFullStopVariant()
	{
		assertSame(ContractCrop.WATERMELON,
			ContractParser.parseAssignment("We need you to grow some Watermelons."));
	}

	/**
	 * Jane names several crops in the plural ("Potatoes", "Watermelons", "Potato cacti"), which is
	 * what the contract-name table keys on. Singular forms are not contract names.
	 */
	@Test
	public void parsesPluralContractNames()
	{
		assertSame(ContractCrop.POTATO,
			ContractParser.parseAssignment("We need you to grow some Potatoes for us?"));
		assertSame(ContractCrop.STRAWBERRY,
			ContractParser.parseAssignment("We need you to grow some Strawberries for us?"));
		assertSame(ContractCrop.POTATO_CACTUS,
			ContractParser.parseAssignment("We need you to grow some Potato cacti for us?"));
		assertNull("the singular is not the contract name",
			ContractParser.parseAssignment("We need you to grow some Potato for us?"));
	}

	@Test
	public void parsesEasyMediumAndHardExamples()
	{
		// Easy
		assertSame(ContractCrop.POTATO,
			ContractParser.parseAssignment("We need you to grow some Potatoes for us?"));
		// Medium
		assertSame(ContractCrop.PAPAYA,
			ContractParser.parseAssignment("We need you to grow a Papaya tree for us?"));
		// Hard
		assertSame(ContractCrop.REDWOOD,
			ContractParser.parseAssignment("We need you to grow a Redwood tree for us?"));
		assertSame(ContractCrop.TORSTOL,
			ContractParser.parseAssignment("We need you to grow some Torstol for us?"));
	}

	@Test
	public void unrelatedDialogueYieldsNoContract()
	{
		assertNull(ContractParser.parseAssignment("Hello there, welcome to the Farming Guild."));
		assertNull(ContractParser.parseAssignment(""));
		assertNull(ContractParser.parseAssignment(null));
	}

	@Test
	public void unknownCropNameYieldsNoContract()
	{
		// Parses structurally but is not a crop we know, so we must not guess.
		assertNull(ContractParser.parseAssignment("We need you to grow some Banana bread for us?"));
	}

	@Test
	public void detectsTheRewardDialogue()
	{
		assertTrue(ContractParser.isContractRewarded(
			"You'll be wanting a reward then. Here you go."));
		assertFalse(ContractParser.isContractRewarded("Here you go."));
		assertFalse(ContractParser.isContractRewarded(null));
	}

	// -------------------------------------------------- 8. game-message parsing

	@Test
	public void detectsContractCancellation()
	{
		assertTrue(ContractParser.isContractCancelled(
			"You have cancelled your current farming contract."));
		assertFalse(ContractParser.isContractCancelled("You plant the maple sapling."));
		assertFalse(ContractParser.isContractCancelled(null));
	}
}

package com.farmingcontract;

import com.farmingcontract.data.ContractCrop;
import com.farmingcontract.farming.CropState;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Contract state transitions, unknown-contract handling and notification de-duplication.
 * Spec test categories 9, 10 and 11.
 */
public class ContractStateTest
{
	private static ContractState state(ContractCrop crop, CropState cropState)
	{
		return new ContractState(crop, cropState, 0, 0L,
			ItemAvailability.unknown(), ItemAvailability.unknown());
	}

	// -------------------------------------------------- 10. unknown-contract handling

	@Test
	public void unknownStateHasNoContract()
	{
		assertFalse(ContractState.UNKNOWN.hasContract());
		assertTrue(ContractState.UNKNOWN.isNotPlanted());
		assertEquals("Not tracked", ContractState.UNKNOWN.getPatchStatusText());
	}

	@Test
	public void anUntrackedPatchIsNotClaimedToBeEmpty()
	{
		ContractState s = state(ContractCrop.MAPLE, null);
		assertTrue(s.hasContract());
		// We have a contract but have never seen the patch: say so rather than "Not planted".
		assertEquals("Not tracked", s.getPatchStatusText());
	}

	// -------------------------------------------------- 9. contract state transitions

	@Test
	public void everyCropStateHasReadableText()
	{
		assertEquals("Not planted", state(ContractCrop.MAPLE, CropState.EMPTY).getPatchStatusText());
		assertEquals("Growing", state(ContractCrop.MAPLE, CropState.GROWING).getPatchStatusText());
		assertEquals("Ready", state(ContractCrop.MAPLE, CropState.HARVESTABLE).getPatchStatusText());
		assertEquals("Diseased", state(ContractCrop.MAPLE, CropState.DISEASED).getPatchStatusText());
		assertEquals("Dead", state(ContractCrop.MAPLE, CropState.DEAD).getPatchStatusText());
		assertEquals("Filling", state(ContractCrop.MAPLE, CropState.FILLING).getPatchStatusText());
	}

	@Test
	public void notPlantedCoversEmptyAndUnobserved()
	{
		assertTrue(state(ContractCrop.MAPLE, CropState.EMPTY).isNotPlanted());
		assertTrue(state(ContractCrop.MAPLE, null).isNotPlanted());
		assertFalse(state(ContractCrop.MAPLE, CropState.GROWING).isNotPlanted());
		assertFalse(state(ContractCrop.MAPLE, CropState.HARVESTABLE).isNotPlanted());
		assertFalse(state(ContractCrop.MAPLE, CropState.DISEASED).isNotPlanted());
	}

	// -------------------------------------------------- 11. duplicate notification prevention

	/**
	 * Mirrors the plugin's notification gate: notify once on becoming ready, and only re-arm after
	 * the patch leaves the ready state.
	 */
	private static class NotifyGate
	{
		private boolean notified;
		private int notifications;

		void observe(CropState cropState)
		{
			if (cropState == CropState.HARVESTABLE)
			{
				if (!notified)
				{
					notifications++;
					notified = true;
				}
			}
			else if (cropState == null || cropState == CropState.EMPTY
				|| cropState == CropState.GROWING)
			{
				notified = false;
			}
		}
	}

	@Test
	public void readyNotifiesOnlyOnceWhileStillReady()
	{
		NotifyGate gate = new NotifyGate();
		gate.observe(CropState.GROWING);
		gate.observe(CropState.HARVESTABLE);
		gate.observe(CropState.HARVESTABLE);
		gate.observe(CropState.HARVESTABLE);
		assertEquals(1, gate.notifications);
	}

	@Test
	public void harvestingThenRegrowingArmsTheNotificationAgain()
	{
		NotifyGate gate = new NotifyGate();
		gate.observe(CropState.HARVESTABLE);
		assertEquals(1, gate.notifications);

		// Harvested and replanted.
		gate.observe(CropState.EMPTY);
		gate.observe(CropState.GROWING);
		gate.observe(CropState.HARVESTABLE);
		assertEquals(2, gate.notifications);
	}

	@Test
	public void diseaseDoesNotReArmTheNotification()
	{
		NotifyGate gate = new NotifyGate();
		gate.observe(CropState.HARVESTABLE);
		gate.observe(CropState.DISEASED);
		gate.observe(CropState.HARVESTABLE);
		// Diseased is not a harvest, so we should not fire a second "ready" notification.
		assertEquals(1, gate.notifications);
	}
}

package com.farmingcontract;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Farming tick arithmetic behind the completion-time estimate.
 */
public class FarmTickTest
{
	private static final int ALLOTMENT_TICK = 10;
	private static final int FRUIT_TREE_TICK = 160;

	@Test
	public void tickTimeAlignsToTheTickBoundary()
	{
		// With no learned offset, ticks align to the raw epoch boundary.
		long boundary = FarmTick.tickTime(ALLOTMENT_TICK, 0, 6_000L, null, null);
		assertEquals(0, boundary % (ALLOTMENT_TICK * 60L));
		assertTrue(boundary <= 6_000L);
	}

	@Test
	public void projectingTicksAheadAddsWholeTicks()
	{
		long now = FarmTick.tickTime(ALLOTMENT_TICK, 0, 6_000L, null, null);
		long threeAhead = FarmTick.tickTime(ALLOTMENT_TICK, 3, 6_000L, null, null);
		assertEquals(3L * ALLOTMENT_TICK * 60L, threeAhead - now);
	}

	@Test
	public void zeroTickRateIsNotEstimable()
	{
		assertEquals(0L, FarmTick.tickTime(0, 2, 6_000L, null, null));
		assertEquals(0L, FarmTick.completionTime(6_000L, 0, 5, 0, null, null));
	}

	@Test
	public void completionTimeCoversRemainingStages()
	{
		// Stage 1 of 5 means 3 more growth ticks to reach the final stage.
		long completion = FarmTick.completionTime(6_000L, 1, 5, ALLOTMENT_TICK, null, null);
		long observedTick = FarmTick.tickTime(ALLOTMENT_TICK, 0, 6_000L, null, null);
		assertEquals(3L * ALLOTMENT_TICK * 60L, completion - observedTick);
	}

	@Test
	public void fullyGrownCropHasNoCompletionEstimate()
	{
		assertEquals(0L, FarmTick.completionTime(6_000L, 4, 5, ALLOTMENT_TICK, null, null));
		assertEquals(0L, FarmTick.completionTime(6_000L, 9, 5, ALLOTMENT_TICK, null, null));
	}

	@Test
	public void unobservedPatchHasNoCompletionEstimate()
	{
		assertEquals(0L, FarmTick.completionTime(0L, 1, 5, ALLOTMENT_TICK, null, null));
	}

	@Test
	public void stageAdvancesWithElapsedTicks()
	{
		long observed = 600_000L;
		long twoTicksLater = observed + 2L * ALLOTMENT_TICK * 60L;
		int stage = FarmTick.currentStage(observed, twoTicksLater, 1, 5, ALLOTMENT_TICK, null, null);
		assertEquals(3, stage);
	}

	@Test
	public void stageIsClampedToTheFinalStage()
	{
		long observed = 600_000L;
		long muchLater = observed + 100L * ALLOTMENT_TICK * 60L;
		int stage = FarmTick.currentStage(observed, muchLater, 1, 5, ALLOTMENT_TICK, null, null);
		assertEquals(4, stage);
	}

	@Test
	public void offsetIsOnlyUsedWhenPreciseEnough()
	{
		// Learned at a coarser granularity than the crop's tick rate, and below the 40 minute
		// fallback threshold: not trustworthy.
		assertFalse(FarmTick.isOffsetUsable(10, 3, FRUIT_TREE_TICK));
		// Learned at 40 minutes or better is trusted for any crop.
		assertTrue(FarmTick.isOffsetUsable(40, 3, FRUIT_TREE_TICK));
		// Learned at least as precisely as this crop's tick rate.
		assertTrue(FarmTick.isOffsetUsable(10, 3, ALLOTMENT_TICK));
		assertFalse(FarmTick.isOffsetUsable(null, 3, ALLOTMENT_TICK));
		assertFalse(FarmTick.isOffsetUsable(10, null, ALLOTMENT_TICK));
	}

	@Test
	public void aUsableOffsetShiftsTheBoundary()
	{
		long without = FarmTick.tickTime(ALLOTMENT_TICK, 0, 6_000L, null, null);
		long with = FarmTick.tickTime(ALLOTMENT_TICK, 0, 6_000L, 3, 40);
		assertTrue(without != with);
		// The shift is the stored offset in minutes, modulo the tick rate.
		assertEquals(-3L * 60L, with - without);
	}
}

package com.farmingcontract;

import com.farmingcontract.data.PatchType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Patch highlight name matching.
 *
 * <p>The Farming Guild contains several objects whose names share the substring "tree patch", which
 * is why matching is exact rather than substring-based. Reported in game: a Magic tree contract
 * highlighted three patches at once.
 */
public class PatchHighlightMatchingTest
{
	/**
	 * Every patch-like object name present in the Farming Guild.
	 */
	private static final String[] GUILD_OBJECT_NAMES = {
		"Allotment", "Flower patch", "Bush patch", "Herb patch", "Tree patch", "Fruit tree patch",
		"Cactus patch", "Celastrus patch", "Redwood tree patch", "Spirit tree patch", "Anima patch",
		"Compost bin", "Big compost bin",
	};

	private static int countMatches(PatchType type)
	{
		int matches = 0;
		for (String name : GUILD_OBJECT_NAMES)
		{
			if (PatchTracker.matchesName(name, type))
			{
				matches++;
			}
		}
		return matches;
	}

	@Test
	public void aTreeContractMatchesExactlyOneGuildPatch()
	{
		// The reported bug highlighted three: Tree patch, Spirit tree patch, Redwood tree patch.
		assertEquals("a tree contract must highlight exactly one patch", 1,
			countMatches(PatchType.TREE));
	}

	@Test
	public void everyPatchTypeMatchesExactlyOneGuildObject()
	{
		for (PatchType type : PatchType.values())
		{
			assertEquals(type + " must match exactly one guild object", 1, countMatches(type));
		}
	}

	@Test
	public void spiritTreeIsNotAnyContractPatch()
	{
		// "Spirit tree patch" contains "tree patch" but is never a contract patch.
		for (PatchType type : PatchType.values())
		{
			assertFalse(type.name(), PatchTracker.matchesName("Spirit tree patch", type));
		}
	}

	@Test
	public void redwoodIsItsOwnPatchAndNotATreePatch()
	{
		// "Redwood tree patch" also contains "tree patch", which both over-matched TREE and stole
		// the patch away from REDWOOD.
		assertFalse(PatchTracker.matchesName("Redwood tree patch", PatchType.TREE));
		assertTrue(PatchTracker.matchesName("Redwood tree patch", PatchType.REDWOOD));
	}

	@Test
	public void fruitTreeAndTreeAreNotConfused()
	{
		assertTrue(PatchTracker.matchesName("Fruit tree patch", PatchType.FRUIT_TREE));
		assertFalse(PatchTracker.matchesName("Fruit tree patch", PatchType.TREE));
		assertTrue(PatchTracker.matchesName("Tree patch", PatchType.TREE));
		assertFalse(PatchTracker.matchesName("Tree patch", PatchType.FRUIT_TREE));
	}

	@Test
	public void eachPatchTypeMatchesItsOwnObjectName()
	{
		assertTrue(PatchTracker.matchesName("Herb patch", PatchType.HERB));
		assertTrue(PatchTracker.matchesName("Flower patch", PatchType.FLOWER));
		assertTrue(PatchTracker.matchesName("Bush patch", PatchType.BUSH));
		assertTrue(PatchTracker.matchesName("Allotment", PatchType.ALLOTMENT));
		assertTrue(PatchTracker.matchesName("Cactus patch", PatchType.CACTUS));
		assertTrue(PatchTracker.matchesName("Celastrus patch", PatchType.CELASTRUS));
	}

	@Test
	public void matchingIsCaseAndWhitespaceInsensitive()
	{
		assertTrue(PatchTracker.matchesName("HERB PATCH", PatchType.HERB));
		assertTrue(PatchTracker.matchesName("herb patch", PatchType.HERB));
		assertTrue(PatchTracker.matchesName("  Herb patch  ", PatchType.HERB));
	}

	@Test
	public void unrelatedObjectsNeverMatch()
	{
		for (PatchType type : PatchType.values())
		{
			assertFalse(type.name(), PatchTracker.matchesName("Bank booth", type));
			assertFalse(type.name(), PatchTracker.matchesName("Compost bin", type));
			assertFalse(type.name(), PatchTracker.matchesName("Anima patch", type));
		}
	}

	@Test
	public void differentPatchTypesDoNotCrossMatch()
	{
		assertFalse(PatchTracker.matchesName("Herb patch", PatchType.FLOWER));
		assertFalse(PatchTracker.matchesName("Flower patch", PatchType.HERB));
		assertFalse(PatchTracker.matchesName("Bush patch", PatchType.CACTUS));
		assertFalse(PatchTracker.matchesName("Allotment", PatchType.HERB));
	}
}

package com.farmingcontract;

import com.farmingcontract.data.ContractCrop;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.when;
import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * Persisted contract loading and account switching, driven through a fake profile config store.
 * Spec test categories 12 and 13.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class ContractManagerTest
{
	@Mock
	private Client client;

	@Mock
	private ConfigManager configManager;

	@Mock
	private ItemManager itemManager;

	private ContractManager manager;

	/**
	 * Stands in for RuneLite's per-RS-profile config store.
	 */
	private final Map<String, String> profileConfig = new HashMap<>();

	@Before
	public void setUp()
	{
		manager = new ContractManager(client, configManager, new InventoryChecker(client, itemManager));

		when(configManager.getRSProfileConfiguration(anyString(), anyString()))
			.thenAnswer(i -> profileConfig.get(key(i.getArgument(0), i.getArgument(1))));

		// The typed overload, used for the notified flag and the farm tick offset.
		when(configManager.getRSProfileConfiguration(anyString(), anyString(), any(Class.class)))
			.thenAnswer(i ->
			{
				String raw = profileConfig.get(key(i.getArgument(0), i.getArgument(1)));
				if (raw == null)
				{
					return null;
				}
				Class<?> type = i.getArgument(2);
				if (type == Boolean.class)
				{
					return Boolean.valueOf(raw);
				}
				if (type == Integer.class)
				{
					try
					{
						return Integer.valueOf(raw);
					}
					catch (NumberFormatException e)
					{
						return null;
					}
				}
				return raw;
			});

		doAnswer(i ->
		{
			// Cast to Object: String.valueOf is overloaded and would otherwise resolve to the
			// char[] variant against Mockito's generic getArgument.
			profileConfig.put(key(i.getArgument(0), i.getArgument(1)),
				String.valueOf((Object) i.getArgument(2)));
			return null;
		}).when(configManager).setRSProfileConfiguration(anyString(), anyString(), any());

		doAnswer(i ->
		{
			profileConfig.remove(key(i.getArgument(0), i.getArgument(1)));
			return null;
		}).when(configManager).unsetRSProfileConfiguration(anyString(), anyString());
	}

	private static String key(String group, String name)
	{
		return group + ":" + name;
	}

	// -------------------------------------------------- 12. persisted contract loading

	@Test
	public void loadsItsOwnPersistedContract()
	{
		profileConfig.put(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT), "MAPLE");

		manager.loadFromConfig();

		assertSame(ContractCrop.MAPLE, manager.getContract());
	}

	@Test
	public void unrecognisedPersistedValueIsDiscardedNotCrashed()
	{
		profileConfig.put(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT),
			"SPACE_POTATO");

		manager.loadFromConfig();

		assertNull(manager.getContract());
	}

	@Test
	public void seedsFromTimeTrackingWhenWeHaveNothingStored()
	{
		// RuneLite's Time Tracking plugin stores the contract as the produce item id.
		profileConfig.put(key("timetracking", "contract"), String.valueOf(ItemID.MAPLE_LOGS));

		manager.loadFromConfig();

		assertSame(ContractCrop.MAPLE, manager.getContract());
		// And it is adopted as our own so we no longer depend on that plugin being enabled.
		assertSame("MAPLE",
			profileConfig.get(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT)));
	}

	@Test
	public void ownValueWinsOverTimeTracking()
	{
		profileConfig.put(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT), "TORSTOL");
		profileConfig.put(key("timetracking", "contract"), String.valueOf(ItemID.MAPLE_LOGS));

		manager.loadFromConfig();

		assertSame(ContractCrop.TORSTOL, manager.getContract());
	}

	@Test
	public void malformedTimeTrackingValueIsIgnored()
	{
		profileConfig.put(key("timetracking", "contract"), "not-a-number");

		manager.loadFromConfig();

		assertNull(manager.getContract());
	}

	@Test
	public void settingAContractPersistsItAndClearingRemovesIt()
	{
		assertTrue(manager.setContract(ContractCrop.YEW));
		assertSame(ContractCrop.YEW, manager.getContract());
		assertSame("YEW",
			profileConfig.get(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT)));

		assertTrue(manager.setContract(null));
		assertNull(manager.getContract());
		assertFalse(profileConfig.containsKey(
			key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT)));
	}

	@Test
	public void settingTheSameContractIsNotAChange()
	{
		manager.setContract(ContractCrop.YEW);
		assertFalse(manager.setContract(ContractCrop.YEW));
	}

	@Test
	public void changingContractResetsTheNotificationFlag()
	{
		manager.setContract(ContractCrop.YEW);
		manager.markNotified();
		assertTrue(manager.isNotifiedReady());

		manager.setContract(ContractCrop.MAPLE);
		assertFalse(manager.isNotifiedReady());
	}

	// -------------------------------------------------- 13. account switching

	@Test
	public void switchingProfileReloadsForTheNewAccount()
	{
		profileConfig.put(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT), "MAPLE");
		manager.loadFromConfig();
		assertSame(ContractCrop.MAPLE, manager.getContract());

		// Second account has a different contract stored.
		profileConfig.put(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT), "TORSTOL");
		manager.onProfileChanged();

		assertSame(ContractCrop.TORSTOL, manager.getContract());
	}

	@Test
	public void switchingToAnAccountWithNoContractClearsTheOldOne()
	{
		profileConfig.put(key(ContractManager.CONFIG_GROUP, ContractManager.KEY_CONTRACT), "MAPLE");
		manager.loadFromConfig();
		assertSame(ContractCrop.MAPLE, manager.getContract());

		profileConfig.clear();
		manager.onProfileChanged();

		assertNull("one account's contract must not leak into another", manager.getContract());
	}

	@Test
	public void notificationFlagIsPersistedPerProfile()
	{
		manager.setContract(ContractCrop.MAPLE);
		manager.markNotified();
		assertTrue(manager.isNotifiedReady());

		// Reload as if logging back in on the same account.
		manager.loadFromConfig();
		assertTrue(manager.isNotifiedReady());
	}
}

