	name = "Farming Contract Helper",
	description = "Shows your current Farming Guild contract, its patch, seed and protection payment",
	tags = {"farming", "contract", "guild", "jane", "skilling", "patch", "seed"}
)
public class FarmingContractHelperPlugin extends Plugin
{
	@Inject
	private ClientThread clientThread;

	@Inject
	private Notifier notifier;

	@Inject
	private PatchTracker patchTracker;

	@Inject
	private FarmingContractHelperConfig config;

	@Inject
	private ContractManager contractManager;

	@Inject
	private InventoryChecker inventoryChecker;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FarmingContractHelperOverlay overlay;

	@Inject
	private FarmingContractPatchOverlay patchOverlay;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	private FarmingContractHelperPanel panel;

	private NavigationButton navButton;

	@Provides
	FarmingContractHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FarmingContractHelperConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new FarmingContractHelperPanel(itemManager, config);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/farmingcontract/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Farming Contract")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlayManager.add(overlay);
		overlayManager.add(patchOverlay);

		clientThread.invokeLater(() ->
		{
			contractManager.loadFromConfig();
			contractManager.observePatches();
			refresh();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(patchOverlay);
		clientToolbar.removeNavigation(navButton);
		contractManager.persistCaches();
		patchTracker.clear();
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Covers logging in and hopping worlds; both re-read the persisted contract and patches.
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			contractManager.loadFromConfig();
			contractManager.observePatches();
			refresh();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			contractManager.persistCaches();
			patchTracker.clear();
		}
		else if (event.getGameState() == GameState.LOADING)
		{
			// Scene is being rebuilt; tracked objects are about to become stale.
			patchTracker.clear();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		contractManager.onProfileChanged();
		refresh();
	}

	@Subscribe
	public void onGameTick(net.runelite.api.events.GameTick event)
	{
		// Jane's dialogue only exists while the player is talking to her in the guild.
		if (contractManager.isInFarmingGuild() && contractManager.checkJaneDialogue())
		{
			contractManager.observePatches();
			refresh();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (contractManager.checkGameMessage(event.getMessage()))
		{
			refresh();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (contractManager.observePatches())
		{
			refresh();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (inventoryChecker.onContainerChanged(event.getContainerId(), event.getItemContainer()))
		{
			contractManager.persistCaches();
			refresh();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		patchTracker.onSpawned(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		patchTracker.onDespawned(event.getGameObject());
	}

	/**
	 * Rebuild the state snapshot and hand it to the UI. Also fires the ready notification once.
	 */
	private void refresh()
	{
		ContractState state = contractManager.buildState(config.checkBank(),
			config.checkSeedVault());

		if (panel != null)
		{
			panel.update(state);
		}
		overlay.setState(state);
		patchOverlay.setState(state);

		handleReadyNotification(state);
	}

	private void handleReadyNotification(ContractState state)
	{
		if (!state.hasContract())
		{
			return;
		}

		if (state.getCropState() == CropState.HARVESTABLE)
		{
			if (!contractManager.isNotifiedReady())
			{
				notifier.notify(config.readyNotification(),
					"Your " + state.getCrop().getContractName() + " contract is ready to check.");
				contractManager.markNotified();
			}
		}
		else if (state.isNotPlanted() || state.getCropState() == CropState.GROWING)
		{
			// Harvested, replanted or cleared: allow the next ready notification through.
			if (contractManager.isNotifiedReady())
			{
				contractManager.resetNotified();
			}
		}
	}
}

package com.farmingcontract;

import com.farmingcontract.data.ContractCrop;
import com.farmingcontract.data.PatchType;
import com.farmingcontract.farming.CropState;
import com.farmingcontract.farming.PatchState;
import com.farmingcontract.farming.Produce;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Works out which farming contract the player has, keeps it persisted per account, and decodes the
 * state of the contract's patch.
 *
 * <p>Detection order, most to least reliable:
 * <ol>
 *     <li>Guildmaster Jane's dialogue, read live while the player talks to her. This is the only
 *     authoritative source in the game — there is no farming contract varbit.</li>
 *     <li>This plugin's own persisted value for the current RuneScape profile.</li>
 *     <li>RuneLite's built-in Time Tracking plugin's stored contract, read through the supported
 *     {@link ConfigManager} profile API. This is a plain config read, not a dependency on that
 *     plugin's classes, and it lets us start with the right contract if the player has used Time
 *     Tracking before installing this plugin.</li>
 * </ol>
 *
 * <p>A crop merely being planted in the Farming Guild is deliberately <b>never</b> treated as
 * evidence of a contract, because players pre-plant crops.
 */
@Slf4j
@Singleton
public class ContractManager
{
	static final String CONFIG_GROUP = "farmingcontracthelper";
	static final String KEY_CONTRACT = "contract";
	static final String KEY_NOTIFIED = "notifiedReady";
	static final String KEY_BANK_CACHE = "bankCache";
	static final String KEY_VAULT_CACHE = "seedVaultCache";
	static final String KEY_PATCH_OBSERVATION = "patchObservation";

	/**
	 * RuneLite's Time Tracking config group, read only for interoperability.
	 */
	private static final String TIMETRACKING_GROUP = "timetracking";
	private static final String TIMETRACKING_CONTRACT = "contract";
	private static final String FARM_TICK_OFFSET = "farmTickOffset";
	private static final String FARM_TICK_OFFSET_PRECISION = "farmTickOffsetPrecision";

	public static final int FARMING_GUILD_REGION_ID = 4922;

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private InventoryChecker inventoryChecker;

	@Inject
	ContractManager()
	{
	}

	/**
	 * Test constructor. Reflection is forbidden in hub plugins, so tests wire dependencies here
	 * rather than poking at private fields.
	 */
	ContractManager(Client client, ConfigManager configManager, InventoryChecker inventoryChecker)
	{
		this.client = client;
		this.configManager = configManager;
		this.inventoryChecker = inventoryChecker;
	}

	@Getter
	@Nullable
	private ContractCrop contract;

	/**
	 * True once we have notified for the current planting, so we do not notify twice.
	 */
	@Getter
	private boolean notifiedReady;

	/**
	 * Last observed varbit value and the unix second we saw it, per patch varbit.
	 */
	private final Map<Integer, long[]> observations = new HashMap<>();

	// ------------------------------------------------------------------ detection

	/**
	 * Inspect Guildmaster Jane's dialogue. Returns true if the contract changed.
	 */
	public boolean checkJaneDialogue()
	{
		Widget head = client.getWidget(InterfaceID.ChatLeft.HEAD);
		if (head == null || head.getModelId() != NpcID.FARMING_GUILD_MASTER)
		{
			return false;
		}

		Widget textWidget = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (textWidget == null)
		{
			return false;
		}

		String dialog = Text.removeTags(textWidget.getText());

		if (ContractParser.isContractRewarded(dialog))
		{
			return setContract(null);
		}

		ContractCrop parsed = ContractParser.parseAssignment(dialog);
		if (parsed == null || parsed == contract)
		{
			return false;
		}

		return setContract(parsed);
	}

	/**
	 * Handle a game message that may cancel the contract. Returns true if the contract changed.
	 */
	public boolean checkGameMessage(String message)
	{
		if (ContractParser.isContractCancelled(Text.removeTags(message)))
		{
			return setContract(null);
		}
		return false;
	}

	/**
	 * Load the contract for the active profile, falling back to RuneLite's Time Tracking value.
	 */
	public void loadFromConfig()
	{
		ContractCrop own = readOwnContract();
		if (own != null)
		{
			contract = own;
		}
		else
		{
			contract = readTimeTrackingContract();
			if (contract != null)
			{
				log.debug("Seeded contract {} from Time Tracking config", contract);
				writeOwnContract(contract);
			}
		}

		Boolean notified = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_NOTIFIED,
			Boolean.class);
		notifiedReady = Boolean.TRUE.equals(notified);

		inventoryChecker.restoreCaches(readCounts(KEY_BANK_CACHE), readCounts(KEY_VAULT_CACHE));
		readObservations();
	}

	@Nullable
	private ContractCrop readOwnContract()
	{
		String stored = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_CONTRACT);
		if (stored == null || stored.isEmpty())
		{
			return null;
		}
		try
		{
			return ContractCrop.valueOf(stored);
		}
		catch (IllegalArgumentException e)
		{
			log.debug("Discarding unrecognised stored contract {}", stored);
			return null;
		}
	}

	/**
	 * Read the contract the built-in Time Tracking plugin persisted, which is stored as the
	 * produce item id.
	 */
	@Nullable
	private ContractCrop readTimeTrackingContract()
	{
		String stored = configManager.getRSProfileConfiguration(TIMETRACKING_GROUP,
			TIMETRACKING_CONTRACT);
		if (stored == null || stored.isEmpty())
		{
			return null;
		}
		try
		{
			Produce produce = Produce.getByItemID(Integer.parseInt(stored));
			return ContractCrop.forProduce(produce);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private void writeOwnContract(@Nullable ContractCrop crop)
	{
		if (crop == null)
		{
			configManager.unsetRSProfileConfiguration(CONFIG_GROUP, KEY_CONTRACT);
		}
		else
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_CONTRACT, crop.name());
		}
	}

	/**
	 * Set the contract, persist it, and reset notification state. Returns true if it changed.
	 */
	public boolean setContract(@Nullable ContractCrop crop)
	{
		if (crop == contract)
		{
			return false;
		}

		contract = crop;
		writeOwnContract(crop);
		resetNotified();
		return true;
	}

	// ------------------------------------------------------------------ notifications

	public void resetNotified()
	{
		notifiedReady = false;
		configManager.unsetRSProfileConfiguration(CONFIG_GROUP, KEY_NOTIFIED);
	}

	public void markNotified()
	{
		notifiedReady = true;
		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_NOTIFIED, true);
	}

	// ------------------------------------------------------------------ patch state

	/**
	 * Record the current value of every patch varbit relevant to the contract. Called on varbit
	 * changes and on login. Returns true if a tracked patch value changed.
	 */
	public boolean observePatches()
	{
		if (contract == null)
		{
			return false;
		}

		boolean changed = false;
		long now = Instant.now().getEpochSecond();

		for (int varbit : contract.getPatchType().getVarbitList())
		{
			int value = client.getVarbitValue(varbit);
			long[] previous = observations.get(varbit);
			if (previous == null || previous[0] != value)
			{
				observations.put(varbit, new long[]{value, now});
				changed = true;
			}
		}

		if (changed)
		{
			writeObservations();
		}
		return changed;
	}

	/**
	 * Decode the contract patch, choosing the patch that actually holds the contract crop when the
	 * patch type is duplicated (the guild's two allotments).
	 */
	@Nullable
	public PatchState getContractPatchState()
	{
		if (contract == null)
		{
			return null;
		}

		PatchType type = contract.getPatchType();
		PatchState fallback = null;

		for (int varbit : type.getVarbitList())
		{
			long[] observation = observations.get(varbit);
			if (observation == null)
			{
				continue;
			}

			PatchState state = type.getImplementation().forVarbitValue((int) observation[0]);
			if (state == null)
			{
				continue;
			}

			if (state.getProduce() == contract.getProduce())
			{
				return state;
			}

			if (fallback == null)
			{
				fallback = state;
			}
		}

		return fallback;
	}

	/**
	 * The unix second at which the patch state used by {@link #getContractPatchState()} was seen.
	 */
	private long getObservationTime()
	{
		if (contract == null)
		{
			return 0L;
		}

		long best = 0L;
		for (int varbit : contract.getPatchType().getVarbitList())
		{
			long[] observation = observations.get(varbit);
			if (observation != null && observation[1] > best)
			{
				best = observation[1];
			}
		}
		return best;
	}

	/**
	 * Build the immutable snapshot the UI renders.
	 */
	public ContractState buildState(boolean checkBank, boolean checkVault)
	{
		if (contract == null)
		{
			return ContractState.UNKNOWN;
		}

		PatchState patch = getContractPatchState();
		ItemAvailability seed = inventoryChecker.checkSeed(contract, checkBank, checkVault);
		ItemAvailability protection = inventoryChecker.checkProtection(contract, checkBank,
			checkVault);

		if (patch == null)
		{
			return new ContractState(contract, null, -1, 0L, seed, protection);
		}

		Integer offset = configManager.getRSProfileConfiguration(TIMETRACKING_GROUP,
			FARM_TICK_OFFSET, Integer.class);
		Integer precision = configManager.getRSProfileConfiguration(TIMETRACKING_GROUP,
			FARM_TICK_OFFSET_PRECISION, Integer.class);

		long observed = getObservationTime();
		int tickRate = patch.getTickRate();
		int stages = patch.getStages();
		int stage = FarmTick.currentStage(observed, Instant.now().getEpochSecond(),
			patch.getStage(), stages, tickRate, offset, precision);
		long completion = FarmTick.completionTime(observed, stage, stages, tickRate, offset,
			precision);

		CropState cropState = patch.getCropState();

		// An empty patch, or one holding something other than the contract crop, is "not planted"
		// as far as the contract is concerned. We never infer a contract from what is planted.
		if (patch.getProduce() != contract.getProduce())
		{
			cropState = CropState.EMPTY;
			completion = 0L;
			stage = -1;
		}

		return new ContractState(contract, cropState, stage, completion, seed, protection);
	}

	// ------------------------------------------------------------------ persistence helpers

	private void writeObservations()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, long[]> entry : observations.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(entry.getKey()).append(':').append(entry.getValue()[0]).append(':')
				.append(entry.getValue()[1]);
		}
		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PATCH_OBSERVATION, sb.toString());
	}

	private void readObservations()
	{
		observations.clear();
		String stored = configManager.getRSProfileConfiguration(CONFIG_GROUP,
			KEY_PATCH_OBSERVATION);
		if (stored == null || stored.isEmpty())
		{
			return;
		}

		for (String entry : stored.split(","))
		{
			String[] parts = entry.split(":");
			if (parts.length != 3)
			{
				continue;
			}
			try
			{
				observations.put(Integer.parseInt(parts[0]),
					new long[]{Long.parseLong(parts[1]), Long.parseLong(parts[2])});
			}
			catch (NumberFormatException ignored)
			{
				// skip malformed entry
			}
		}
	}

	/**
	 * Persist the last seen bank and seed vault counts so they survive a relog.
	 */
	public void persistCaches()
	{
		writeCounts(KEY_BANK_CACHE, inventoryChecker.getBankCache());
		writeCounts(KEY_VAULT_CACHE, inventoryChecker.getSeedVaultCache());
	}

	private void writeCounts(String key, Map<Integer, Integer> counts)
	{
		if (counts.isEmpty())
		{
			return;
		}

		// Only the items this plugin could ever ask about are worth persisting.
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, Integer> entry : counts.entrySet())
		{
			if (!RELEVANT_ITEMS.contains(entry.getKey()))
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(entry.getKey()).append(':').append(entry.getValue());
		}
		configManager.setRSProfileConfiguration(CONFIG_GROUP, key, sb.toString());
	}

	private Map<Integer, Integer> readCounts(String key)
	{
		Map<Integer, Integer> out = new HashMap<>();
		String stored = configManager.getRSProfileConfiguration(CONFIG_GROUP, key);
		if (stored == null || stored.isEmpty())
		{
			return out;
		}

		for (String entry : stored.split(","))
		{
			String[] parts = entry.split(":");
			if (parts.length != 2)
			{
				continue;
			}
			try
			{
				out.put(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
			}
			catch (NumberFormatException ignored)
			{
				// skip malformed entry
			}
		}
		return out;
	}

	/**
	 * Every item this plugin can ask about, so persisted caches stay small.
	 */
	private static final java.util.Set<Integer> RELEVANT_ITEMS = buildRelevantItems();

	private static java.util.Set<Integer> buildRelevantItems()
	{
		java.util.Set<Integer> items = new java.util.HashSet<>();
		for (ContractCrop crop : ContractCrop.values())
		{
			items.add(crop.getSeedItemId());
			if (crop.getProtection().isAvailable())
			{
				items.add(crop.getProtection().getItemId());
				if (crop.getProtection().isContainerRequired())
				{
					items.add(crop.getProtection().getLooseItemId());
				}
			}
		}
		return items;
	}

	/**
	 * Wipe volatile state when the profile changes so one account never shows another's data.
	 */
	public void onProfileChanged()
	{
		contract = null;
		notifiedReady = false;
		observations.clear();
		inventoryChecker.reset();
		loadFromConfig();
	}

	public boolean isInFarmingGuild()
	{
		net.runelite.api.WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return false;
		}

		int[] mapRegions = worldView.getMapRegions();
		if (mapRegions == null)
		{
			return false;
		}
		for (int region : mapRegions)
		{
			if (region == FARMING_GUILD_REGION_ID)
			{
				return true;
			}
		}
		return false;
	}
}

package com.farmingcontract.ui;

import com.farmingcontract.ContractManager;
import com.farmingcontract.ContractState;
import com.farmingcontract.FarmingContractHelperConfig;
import com.farmingcontract.PatchTracker;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import net.runelite.api.GameObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Outlines the Farming Guild patch the current contract belongs in, with a small label.
 *
 * <p>Patch objects come from {@link PatchTracker}, which maintains them from spawn and despawn
 * events. This overlay runs every frame, so it must not do any scene scanning itself.
 *
 * <p>Known limitation: the Farming Guild has two allotment patches sharing an object name, so an
 * allotment contract highlights both.
 */
@Singleton
public class FarmingContractPatchOverlay extends Overlay
{
	private static final Color OUTLINE = new Color(0, 200, 83, 180);
	private static final Color FILL = new Color(0, 200, 83, 30);

	private final FarmingContractHelperConfig config;
	private final ContractManager contractManager;
	private final PatchTracker patchTracker;

	@Setter
	private ContractState state = ContractState.UNKNOWN;

	@Inject
	private FarmingContractPatchOverlay(FarmingContractHelperConfig config,
		ContractManager contractManager, PatchTracker patchTracker)
	{
		this.config = config;
		this.contractManager = contractManager;
		this.patchTracker = patchTracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightPatch() || !state.hasContract()
			|| !contractManager.isInFarmingGuild())
		{
			return null;
		}

		String label = "Current contract: " + state.getCrop().getContractName();

		for (GameObject object : patchTracker.getPatches(state.getCrop().getPatchType()))
		{
			Shape hull = object.getConvexHull();
			if (hull == null)
			{
				continue;
			}

			OverlayUtil.renderPolygon(graphics, hull, OUTLINE, FILL, graphics.getStroke());
			OverlayUtil.renderTextLocation(graphics,
				object.getCanvasTextLocation(graphics, label, 60), label, OUTLINE);
		}

		return null;
	}
}

package com.farmingcontract.ui;

import com.farmingcontract.ContractState;
import com.farmingcontract.FarmingContractHelperConfig;
import com.farmingcontract.ItemAvailability;
import com.farmingcontract.data.ContractCrop;
import com.farmingcontract.data.ProtectionPayment;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Compact on-screen summary of the contract, built from RuneLite's standard overlay components so
 * it matches every other plugin.
 */
@Singleton
public class FarmingContractHelperOverlay extends OverlayPanel
{
	private static final Color GOOD = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color BAD = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color UNSURE = ColorScheme.LIGHT_GRAY_COLOR;

	/**
	 * Have it, but in the bank or vault rather than carried.
	 */
	private static final Color STORAGE = ColorScheme.PROGRESS_INPROGRESS_COLOR;

	private final FarmingContractHelperConfig config;

	@Setter
	private ContractState state = ContractState.UNKNOWN;

	@Inject
	private FarmingContractHelperOverlay(FarmingContractHelperConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		getMenuEntries().add(new OverlayMenuEntry(
			net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG,
			"Configure", "Farming Contract Helper overlay"));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Farming Contract")
			.color(ColorScheme.BRAND_ORANGE)
			.build());

		if (!state.hasContract())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Unknown")
				.right("Ask Jane")
				.rightColor(UNSURE)
				.build());
			panelComponent.setPreferredSize(new Dimension(160, 0));
			return super.render(graphics);
		}

		ContractCrop crop = state.getCrop();

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Contract:")
			.right(crop.getContractName())
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Patch:")
			.right(crop.getPatchType().getDisplayName())
			.build());

		panelComponent.getChildren().add(itemLine("Seed:",
			crop.getSeedQuantity() + " " + crop.getSeedName(), state.getSeed()));

		if (config.showProtection())
		{
			ProtectionPayment payment = crop.getProtection();
			if (payment.isAvailable())
			{
				panelComponent.getChildren().add(itemLine("Payment:",
					payment.getDescription(), state.getProtection()));
			}
			else
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Payment:")
					.right("Not available")
					.rightColor(UNSURE)
					.build());
			}
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Status:")
			.right(state.getPatchStatusText())
			.rightColor(state.getCropState() == null ? UNSURE : state.getCropState().getColor())
			.build());

		String ready = readyText(state);
		if (ready != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Ready:")
				.right(ready)
				.build());
		}

		panelComponent.setPreferredSize(new Dimension(200, 0));
		return super.render(graphics);
	}

	/**
	 * A line marked with how available the item is. Uses the same four states as the side panel:
	 * carried, carried as a note, in storage, unknown, missing.
	 */
	private LineComponent itemLine(String left, String right, ItemAvailability availability)
	{
		if (!config.checkInventory() || availability.isNotRequired())
		{
			return LineComponent.builder().left(left).right(right).build();
		}

		String mark;
		Color color;
		switch (availability.getStatus())
		{
			case HAVE:
				mark = " ✓";
				color = GOOD;
				break;
			case HAVE_NOTED:
				mark = " ✓ (noted)";
				color = GOOD;
				break;
			case IN_STORAGE:
				mark = " ◆ " + availability.getStorageDescription();
				color = STORAGE;
				break;
			case MISSING:
				mark = " ✗";
				color = BAD;
				break;
			case UNKNOWN:
			default:
				mark = " ?";
				color = UNSURE;
				break;
		}

		return LineComponent.builder()
			.left(left)
			.right(right + mark)
			.rightColor(color)
			.build();
	}

	private static String readyText(ContractState state)
	{
		if (state.getCompletionTime() <= 0L)
		{
			return null;
		}

		Duration remaining = Duration.between(Instant.now(),
			Instant.ofEpochSecond(state.getCompletionTime()));
		if (remaining.isNegative() || remaining.isZero())
		{
			return "now";
		}

		long hours = remaining.toHours();
		long minutes = remaining.toMinutes() % 60;
		return hours > 0 ? hours + "h " + minutes + "m" : minutes + "m";
	}
}

package com.farmingcontract.ui;

import com.farmingcontract.ContractState;
import com.farmingcontract.FarmingContractHelperConfig;
import com.farmingcontract.ItemAvailability;
import com.farmingcontract.data.ContractCrop;
import com.farmingcontract.data.ContractTier;
import com.farmingcontract.data.ProtectionPayment;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.Duration;
import java.time.Instant;
import java.util.StringJoiner;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Side panel showing the current contract, broken into the sections the player needs while
 * prepping: what the contract is, where the patch is, what to plant, what to pay, and how it is
 * doing.
 */
public class FarmingContractHelperPanel extends PluginPanel
{
	private static final Color GOOD = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color BAD = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color UNSURE = ColorScheme.LIGHT_GRAY_COLOR;

	/**
	 * Have it, but it is in the bank or vault rather than on you.
	 */
	private static final Color STORAGE = ColorScheme.PROGRESS_INPROGRESS_COLOR;

	private final ItemManager itemManager;
	private final FarmingContractHelperConfig config;

	private final JLabel cropIcon = new JLabel();
	private final JLabel cropName = new JLabel();
	private final JPanel sections = new JPanel();

	public FarmingContractHelperPanel(ItemManager itemManager, FarmingContractHelperConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel header = new JPanel(new BorderLayout(8, 0));
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 10, 0));
		cropName.setFont(FontManager.getRunescapeBoldFont());
		cropName.setForeground(Color.WHITE);
		header.add(cropIcon, BorderLayout.WEST);
		header.add(cropName, BorderLayout.CENTER);

		sections.setLayout(new GridLayout(0, 1, 0, 8));

		add(header, BorderLayout.NORTH);
		add(sections, BorderLayout.CENTER);

		update(ContractState.UNKNOWN);
	}

	public void update(ContractState state)
	{
		SwingUtilities.invokeLater(() -> rebuild(state));
	}

	private void rebuild(ContractState state)
	{
		sections.removeAll();
		cropIcon.setIcon(null);

		if (!state.hasContract())
		{
			cropName.setText("Contract unknown");
			sections.add(section("", wrapped(
				"Talk to Guildmaster Jane and ask about your current contract.")));
			sections.revalidate();
			sections.repaint();
			return;
		}

		ContractCrop crop = state.getCrop();

		cropName.setText(crop.getContractName());
		AsyncBufferedImage image = itemManager.getImage(crop.getProduceItemId());
		cropIcon.setIcon(new ImageIcon(image));
		image.onLoaded(() -> cropIcon.setIcon(new ImageIcon(image)));

		sections.add(section("Contract", label(crop.getContractName() + tierSuffix(crop), Color.WHITE)));

		sections.add(section("Patch", multi(
			label(crop.getPatchType().getDisplayName() + " patch", Color.WHITE),
			wrapped(crop.getPatchType().getLocationDescription()))));

		sections.add(section("Required items", requiredItems(crop, state.getSeed())));

		if (config.showProtection())
		{
			sections.add(section("Protection", protectionSection(crop, state.getProtection())));
		}

		sections.add(section("Patch status", label(state.getPatchStatusText(),
			state.getCropState() == null ? UNSURE : state.getCropState().getColor())));

		sections.add(section("Completion time", label(completionText(state), Color.WHITE)));

		sections.revalidate();
		sections.repaint();
	}

	private static String tierSuffix(ContractCrop crop)
	{
		StringJoiner joiner = new StringJoiner("/");
		for (ContractTier tier : ContractTier.values())
		{
			if (crop.getTiers().contains(tier))
			{
				joiner.add(tier.getDisplayName());
			}
		}
		return "  (" + joiner + ")";
	}

	private JPanel requiredItems(ContractCrop crop, ItemAvailability seed)
	{
		String text = crop.getSeedQuantity() + " " + crop.getSeedName();
		if (!config.checkInventory())
		{
			return multi(label(text, Color.WHITE));
		}
		return multi(label(text, Color.WHITE), availabilityLabel(seed));
	}

	private JPanel protectionSection(ContractCrop crop, ItemAvailability protection)
	{
		ProtectionPayment payment = crop.getProtection();

		if (!payment.isAvailable())
		{
			return multi(label("Not available", UNSURE));
		}

		JPanel panel = multi(label(payment.getDescription(), Color.WHITE));

		if (payment.isContainerRequired())
		{
			panel.add(wrapped("Contents: " + payment.getContentsDescription()));
			panel.add(wrapped("The gardener only accepts filled "
				+ (payment.getQuantity() == 1 ? "containers" : "containers")
				+ " — loose produce must be put into them first."));
		}

		if (config.checkInventory())
		{
			panel.add(availabilityLabel(protection));
		}

		return panel;
	}

	/**
	 * Render availability honestly. Green when usable now, amber when the player has it but not on
	 * them, red only when we are certain they are short, grey when a container we would need has
	 * never been opened.
	 */
	private JLabel availabilityLabel(ItemAvailability availability)
	{
		switch (availability.getStatus())
		{
			case NOT_REQUIRED:
				return label("", UNSURE);

			case HAVE:
				return label("✓ In inventory (" + availability.getInventoryProgress() + ")", GOOD);

			case HAVE_NOTED:
				return label("✓ In inventory, noted ("
					+ availability.getInventoryProgress() + ")", GOOD);

			case IN_STORAGE:
			{
				String where = availability.getStorageDescription();
				String note = availability.hasUnusableNote() ? "  —  un-note to plant" : "";
				return label("◆ Not carried, in " + where + note, STORAGE);
			}

			case UNKNOWN:
			{
				StringBuilder sb = new StringBuilder();
				sb.append("? Inventory: ").append(availability.getInventoryProgress());
				String where = availability.getStorageDescription();
				if (where != null)
				{
					sb.append("  |  ").append(where);
				}
				sb.append("  |  elsewhere unknown");
				return label(sb.toString(), UNSURE);
			}

			case MISSING:
			default:
			{
				String note = availability.hasUnusableNote() ? "  (noted only — un-note first)" : "";
				return label("✗ Missing: " + availability.getInventoryProgress() + note, BAD);
			}
		}
	}

	private static String completionText(ContractState state)
	{
		if (state.getCompletionTime() <= 0L)
		{
			return state.isNotPlanted() ? "Not planted" : "Unknown";
		}

		Duration remaining = Duration.between(Instant.now(),
			Instant.ofEpochSecond(state.getCompletionTime()));
		if (remaining.isNegative() || remaining.isZero())
		{
			return "Ready";
		}

		long hours = remaining.toHours();
		long minutes = remaining.toMinutes() % 60;
		return hours > 0 ? hours + "h " + minutes + "m" : minutes + "m";
	}

	// ------------------------------------------------------------------ small layout helpers

	private static JPanel section(String title, JPanel content)
	{
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

		if (!title.isEmpty())
		{
			JLabel heading = new JLabel(title);
			heading.setFont(FontManager.getRunescapeSmallFont());
			heading.setForeground(ColorScheme.BRAND_ORANGE);
			panel.add(heading, BorderLayout.NORTH);
		}

		panel.add(content, BorderLayout.CENTER);
		return panel;
	}

	private static JPanel section(String title, JLabel content)
	{
		return section(title, multi(content));
	}

	private static JPanel multi(JLabel... labels)
	{
		JPanel panel = new JPanel(new GridLayout(0, 1, 0, 2));
		panel.setOpaque(false);
		for (JLabel label : labels)
		{
			panel.add(label);
		}
		return panel;
	}

	private static JLabel label(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeSmallFont());
		return label;
	}

	/**
	 * A label that wraps, for location descriptions and notes.
	 */
	private static JLabel wrapped(String text)
	{
		JLabel label = new JLabel("<html><body style='width:150px'>" + text + "</body></html>");
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, label.getPreferredSize().height));
		return label;
	}
}

package com.farmingcontract.data;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Farming Guild contract difficulty tiers, as offered by Guildmaster Jane.
 * A crop may be offered by more than one tier.
 */
@Getter
@RequiredArgsConstructor
public enum ContractTier
{
	EASY("Easy", 45),
	MEDIUM("Medium", 65),
	HARD("Hard", 85);

	private final String displayName;

	/**
	 * Farming level at which this tier of contract becomes available.
	 */
	private final int farmingLevel;
}

package com.farmingcontract.data;

import javax.annotation.Nullable;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;

/**
 * A gardener protection payment for one specific crop.
 *
 * <p>The gardener requires payment <b>in the exact form requested</b>. Where that form is a
 * filled basket or sack, the loose produce is recorded separately via {@link #looseItemId} so the
 * plugin can tell the player how much raw produce a batch needs — but loose produce is
 * deliberately <b>not</b> treated as payable. See {@link #isContainerRequired()}.
 */
@Getter
@RequiredArgsConstructor
public class ProtectionPayment
{
	/**
	 * A crop that the gardener will not protect at any price (herbs and flowers), or that needs
	 * no protection because it cannot become diseased (poison ivy).
	 */
	public static final ProtectionPayment NONE = new ProtectionPayment(-1, "", 0, -1, "", 0);

	/**
	 * How many loose fruit fill one basket.
	 */
	public static final int BASKET_CAPACITY = 5;

	/**
	 * How many loose vegetables fill one sack.
	 */
	public static final int SACK_CAPACITY = 10;

	/**
	 * Item the gardener actually accepts.
	 */
	private final int itemId;

	private final String itemName;

	/**
	 * How many of {@link #itemId} the gardener wants.
	 */
	private final int quantity;

	/**
	 * When the payment is a filled basket or sack, the loose produce that fills it; otherwise -1.
	 */
	private final int looseItemId;

	private final String looseItemName;

	/**
	 * Total loose produce needed to fill {@link #quantity} containers; 0 when not a container.
	 */
	private final int looseQuantity;

	/**
	 * A payment made directly in loose items, e.g. 10 jute fibre.
	 */
	public static ProtectionPayment loose(int itemId, String itemName, int quantity)
	{
		return new ProtectionPayment(itemId, itemName, quantity, -1, "", 0);
	}

	/**
	 * A payment that must be handed over as filled baskets.
	 */
	public static ProtectionPayment baskets(int filledBasketId, String basketName, int baskets,
		int looseItemId, String looseItemName)
	{
		return new ProtectionPayment(filledBasketId, basketName, baskets,
			looseItemId, looseItemName, baskets * BASKET_CAPACITY);
	}

	/**
	 * A payment that must be handed over as filled sacks.
	 */
	public static ProtectionPayment sacks(int filledSackId, String sackName, int sacks,
		int looseItemId, String looseItemName)
	{
		return new ProtectionPayment(filledSackId, sackName, sacks,
			looseItemId, looseItemName, sacks * SACK_CAPACITY);
	}

	/**
	 * Two buckets of compost, the potato contract's payment.
	 */
	public static ProtectionPayment compost(int quantity)
	{
		return loose(ItemID.BUCKET_COMPOST, "Bucket of compost", quantity);
	}

	public boolean isAvailable()
	{
		return itemId != -1;
	}

	/**
	 * True when the gardener insists on a filled basket or sack, meaning loose produce in the
	 * inventory is <b>not</b> immediately payable.
	 */
	public boolean isContainerRequired()
	{
		return looseItemId != -1;
	}

	@Nullable
	public String getContentsDescription()
	{
		if (!isContainerRequired())
		{
			return null;
		}
		return looseQuantity + " " + looseItemName;
	}

	public String getDescription()
	{
		if (!isAvailable())
		{
			return "Not available";
		}
		return quantity + " " + itemName;
	}
}

package com.farmingcontract.data;

import com.farmingcontract.farming.PatchImplementation;
import java.util.Collections;
import java.util.List;
import lombok.Getter;
import net.runelite.api.gameval.VarbitID;

/**
 * The Farming Guild patch types that can host a farming contract crop.
 *
 * <p>Varbit assignments and patch/region layout are taken from RuneLite's
 * {@code FarmingWorld} definition of the Farming Guild (region 4922). Allotments are the only
 * duplicated patch type in the guild, so they carry two varbits.
 */
@Getter
public enum PatchType
{
	ALLOTMENT(
		"Allotment",
		"Allotment",
		"Allotment patch, Farming Guild lower tier",
		PatchImplementation.ALLOTMENT,
		3,
		VarbitID.FARMING_TRANSMIT_C,
		VarbitID.FARMING_TRANSMIT_D),

	FLOWER(
		"Flower",
		"Flower patch",
		"Flower patch, Farming Guild lower tier",
		PatchImplementation.FLOWER,
		1,
		VarbitID.FARMING_TRANSMIT_H),

	BUSH(
		"Bush",
		"Bush patch",
		"Bush patch, Farming Guild lower tier",
		PatchImplementation.BUSH,
		1,
		VarbitID.FARMING_TRANSMIT_B),

	HERB(
		"Herb",
		"Herb patch",
		"Herb patch, Farming Guild middle tier",
		PatchImplementation.HERB,
		1,
		VarbitID.FARMING_TRANSMIT_E),

	TREE(
		"Tree",
		"Tree patch",
		"Tree patch, west side of Farming Guild middle tier",
		PatchImplementation.TREE,
		1,
		VarbitID.FARMING_TRANSMIT_G),

	FRUIT_TREE(
		"Fruit tree",
		"Fruit tree patch",
		"Fruit tree patch, Farming Guild upper tier",
		PatchImplementation.FRUIT_TREE,
		1,
		VarbitID.FARMING_TRANSMIT_K),

	CACTUS(
		"Cactus",
		"Cactus patch",
		"Cactus patch, Farming Guild upper tier",
		PatchImplementation.CACTUS,
		1,
		VarbitID.FARMING_TRANSMIT_F),

	CELASTRUS(
		"Celastrus",
		"Celastrus patch",
		"Celastrus patch, Farming Guild upper tier",
		PatchImplementation.CELASTRUS,
		1,
		VarbitID.FARMING_TRANSMIT_L),

	REDWOOD(
		"Redwood",
		"Redwood tree patch",
		"Redwood patch, Farming Guild upper tier",
		PatchImplementation.REDWOOD,
		1,
		VarbitID.FARMING_TRANSMIT_I);

	private final String displayName;

	/**
	 * Exact scene object name for this patch in the Farming Guild.
	 *
	 * <p>Matched with equality, not substring: the guild also contains a "Spirit tree patch" and a
	 * "Redwood tree patch", both of which contain the substring "tree patch" and would otherwise be
	 * highlighted for an ordinary tree contract.
	 */
	private final String objectName;

	/**
	 * Human-readable location, understandable without a map.
	 */
	private final String locationDescription;

	/**
	 * Vendored RuneLite decoder used to turn a patch varbit value into produce + crop state.
	 */
	private final PatchImplementation implementation;

	/**
	 * How many seeds or saplings one planting of this patch type consumes.
	 * Allotments take three seeds; every other contract patch takes one.
	 */
	private final int plantQuantity;

	private final int[] varbits;

	PatchType(String displayName, String objectName, String locationDescription,
		PatchImplementation implementation, int plantQuantity, int... varbits)
	{
		this.displayName = displayName;
		this.objectName = objectName;
		this.locationDescription = locationDescription;
		this.implementation = implementation;
		this.plantQuantity = plantQuantity;
		this.varbits = varbits;
	}

	public List<Integer> getVarbitList()
	{
		List<Integer> out = new java.util.ArrayList<>(varbits.length);
		for (int v : varbits)
		{
			out.add(v);
		}
		return Collections.unmodifiableList(out);
	}
}

package com.farmingcontract;

import com.farmingcontract.data.PatchType;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;

/**
 * Keeps track of the Farming Guild patch objects currently in the scene.
 *
 * <p>Driven by object spawn and despawn events rather than by scanning the scene, because the patch
 * highlight overlay runs every frame and walking the whole scene there would be far too expensive.
 * Farming patches are varbit-transformed objects, so changing crop or growth stage produces a
 * despawn followed by a spawn, which keeps this collection correct.
 */
@Singleton
public class PatchTracker
{
	private final Map<PatchType, List<GameObject>> patches = new EnumMap<>(PatchType.class);

	@Inject
	private Client client;

	public void onSpawned(GameObject object)
	{
		PatchType type = classify(object);
		if (type != null)
		{
			patches.computeIfAbsent(type, k -> new ArrayList<>()).add(object);
		}
	}

	public void onDespawned(GameObject object)
	{
		// The composition may already have transformed, so remove by identity from every bucket.
		for (List<GameObject> list : patches.values())
		{
			list.removeIf(tracked -> tracked == object
				|| tracked.getHash() == object.getHash());
		}
	}

	public void clear()
	{
		patches.clear();
	}

	public List<GameObject> getPatches(PatchType type)
	{
		List<GameObject> list = patches.get(type);
		return list == null ? Collections.emptyList() : Collections.unmodifiableList(list);
	}

	/**
	 * Which patch type this scene object is, or null if it is not a farming patch we care about.
	 * Resolves varbit-transformed objects to their impostor before reading the name.
	 */
	private PatchType classify(GameObject object)
	{
		ObjectComposition composition = client.getObjectDefinition(object.getId());
		if (composition == null)
		{
			return null;
		}

		if (composition.getImpostorIds() != null && composition.getImpostor() != null)
		{
			composition = composition.getImpostor();
		}

		String name = composition.getName();
		if (name == null || name.isEmpty() || "null".equals(name))
		{
			return null;
		}

		for (PatchType type : PatchType.values())
		{
			if (matchesName(name, type))
			{
				return type;
			}
		}
		return null;
	}

	/**
	 * Name matching for each patch type, kept static and side-effect free so it can be unit-tested.
	 *
	 * <p><b>Exact equality, deliberately.</b> Substring matching is wrong here: the Farming Guild
	 * contains a "Spirit tree patch" and a "Redwood tree patch" alongside the ordinary "Tree patch",
	 * so {@code contains("tree patch")} highlights three patches for one tree contract and also
	 * steals the redwood patch away from {@link PatchType#REDWOOD}.
	 */
	static boolean matchesName(String objectName, PatchType patchType)
	{
		return patchType.getObjectName().equalsIgnoreCase(objectName.trim());
	}
}

package com.farmingcontract;

import com.farmingcontract.data.ContractCrop;
import com.farmingcontract.farming.CropState;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * An immutable snapshot of everything the UI needs to render: the contract, where its patch stands,
 * and whether the required items are to hand.
 *
 * <p>Runtime state only — static crop facts live in {@link ContractCrop}.
 */
@Value
public class ContractState
{
	/**
	 * The state shown before we have ever seen a contract for this account.
	 */
	public static final ContractState UNKNOWN =
		new ContractState(null, null, -1, 0L, ItemAvailability.unknown(), ItemAvailability.unknown());

	/**
	 * Null when the contract could not be determined.
	 */
	@Nullable
	ContractCrop crop;

	/**
	 * Null when the patch has not been observed this session, or the crop is not planted.
	 */
	@Nullable
	CropState cropState;

	/**
	 * Growth stage within {@link #cropState}, or -1 when unknown.
	 */
	int stage;

	/**
	 * Epoch millis at which the crop finishes growing, or 0 when not estimable.
	 */
	long completionTime;

	ItemAvailability seed;

	ItemAvailability protection;

	public boolean hasContract()
	{
		return crop != null;
	}

	/**
	 * True when the patch has been read and holds nothing of the contract crop.
	 */
	public boolean isNotPlanted()
	{
		return cropState == null || cropState == CropState.EMPTY;
	}

	public String getPatchStatusText()
	{
		if (cropState == null)
		{
			return "Not tracked";
		}

		switch (cropState)
		{
			case EMPTY:
				return "Not planted";
			case GROWING:
				return "Growing";
			case HARVESTABLE:
				return "Ready";
			case DISEASED:
				return "Diseased";
			case DEAD:
				return "Dead";
			case FILLING:
				return "Filling";
			default:
				return cropState.name();
		}
	}
}

